import { useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { fetchAllDeliveryMethods, fetchOrgDeliveryMethods, assignDeliveryMethod, removeDeliveryMethod } from '../../redux/slices/OrganizationSlice';

const DeliveryMethodsSection = ({ orgId }) => {
  const dispatch = useDispatch();
  const token = useSelector((state) => state.auth.token);
  const { 
    allDeliveryMethods, 
    orgDeliveryMethods, 
    loadingDeliveryMethods, 
    deliveryMethodsError 
  } = useSelector((state) => state.organization);

  const loading = loadingDeliveryMethods.deliveryMethods || loadingDeliveryMethods.deliveryMethodAssignments;
  const error = deliveryMethodsError;

  useEffect(() => {
    if (token && orgId) {
      dispatch(fetchAllDeliveryMethods());
      dispatch(fetchOrgDeliveryMethods(orgId));
    }
  }, [dispatch, token, orgId]);

  const handleCheckboxChange = async (methodId, isChecked) => {
    if (!token || !orgId) return;

    try {
      if (isChecked) {
        await dispatch(assignDeliveryMethod({ orgId, methodId }));
      } else {
        await dispatch(removeDeliveryMethod({ orgId, methodId }));
      }
    } catch (err) {
      console.error('Error updating delivery method:', err);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-md border border-gray-200 p-6 w-full min-h-[400px]">
      <div className="flex justify-between items-center mb-4">
        <h3 className="text-lg font-semibold text-gray-800 flex items-center gap-2">
          <svg className="h-5 w-5" viewBox="0 0 48 48" xmlns="http://www.w3.org/2000/svg">
            <g id="Layer_2" data-name="Layer 2">
              <g id="invisible_box" data-name="invisible box">
                <rect width="48" height="48" fill="none"/>
              </g>
              <g id="Layer_7" data-name="Layer 7">
                <g>
                  <path fill="#2563eb" d="M37.7,11.1A3,3,0,0,0,35.4,10H34.2l.3-1.7A3.1,3.1,0,0,0,33.9,6a3.2,3.2,0,0,0-2.2-1H7.9A2.1,2.1,0,0,0,5.8,6.7,2,2,0,0,0,7.8,9h7.3A3,3,0,0,1,18,12.5L15.6,26.3a3,3,0,0,1-2.9,2.5H4.8a2,2,0,0,0-2,1.6L2,34.7A2.8,2.8,0,0,0,2.7,37a2.8,2.8,0,0,0,2.1,1H7.3a7,7,0,0,0,13.4,0h4.6a7,7,0,0,0,13.4,0h2a3.2,3.2,0,0,0,3.1-2.7L46,22.5ZM14,39a3,3,0,0,1-3-3,3,3,0,0,1,6,0A3,3,0,0,1,14,39Zm18,0a3,3,0,0,1-3-3,3,3,0,0,1,6,0A3,3,0,0,1,32,39Zm.1-17,1.4-8h1.3l5.9,8Z"/>
                  <path fill="#2563eb" d="M4,15H14a2,2,0,0,0,0-4H4a2,2,0,0,0,0,4Z"/>
                  <path fill="#2563eb" d="M15,19a2,2,0,0,0-2-2H5a2,2,0,0,0,0,4h8A2,2,0,0,0,15,19Z"/>
                  <path fill="#2563eb" d="M6,23a2,2,0,0,0,0,4h6a2,2,0,0,0,0-4Z"/>
                </g>
              </g>
            </g>
          </svg>
          Способы доставки
        </h3>
      </div>
      
      {loading ? (
        <div className="animate-pulse space-y-2">
          <div className="h-4 bg-gray-200 rounded w-full"></div>
          <div className="h-4 bg-gray-200 rounded w-3/4"></div>
        </div>
      ) : error ? (
        <div className="text-red-600 text-sm">Ошибка: {error}</div>
      ) : (
        <div className="space-y-2">
          {allDeliveryMethods && allDeliveryMethods.length > 0 ? (
            allDeliveryMethods.map(method => {
              const isChecked = orgDeliveryMethods.some(orgMethod => orgMethod.id === method.id);
              return (
                <div key={method.id} className="flex justify-between items-center p-3 bg-gray-50 rounded border min-h-[52px]">
                  <div className="truncate pr-2">
                    <span className="font-medium">{method.name}</span>
                    {method.description && <span className="ml-2 text-sm text-gray-600">- {method.description}</span>}
                  </div>
                  <label className="inline-flex items-center cursor-pointer">
                    <input
                      type="checkbox"
                      checked={isChecked}
                      onChange={(e) => {
                        e.stopPropagation();
                        handleCheckboxChange(method.id, e.target.checked);
                      }}
                      className="sr-only peer"
                      disabled={loading}
                    />
                    <div className={`relative w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 dark:peer-focus:ring-blue-800 rounded-full peer dark:bg-gray-700 peer-checked:after:translate-x-full rtl:peer-checked:after:-translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:start-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all after:duration-300 ease-in-out dark:border-gray-600 peer-checked:bg-blue-600 ${loading ? 'opacity-50' : ''}`}>
                      <div className="absolute inset-0 flex items-center justify-center text-xs text-white font-bold opacity-0 peer-checked:opacity-100 transition-opacity duration-300">
                        ✓
                      </div>
                    </div>
                  </label>
                </div>
              );
            })
          ) : (
            <p className="text-gray-500 italic">Нет доступных способов доставки</p>
          )}
        </div>
      )}
    </div>
  );
};

export default DeliveryMethodsSection;